// Production (M4) base migration for the Admin API role: identity/session/replay/audit privileges, support tables and the
// one additive schema change the Admin queries need on Production (`products.version`, used for optimistic locking).
// Generated by scripts/m4/generate-production-admin-migration.mts; the resource grants come from grants.ts (002).
export interface BaseOptions { role: string; policyPrefix: string; guard: string; title: string }

export const PRODUCTION_GUARD = `do $$ begin
  if not exists (select 1 from pg_roles where rolname = 'dpg_public_catalogue') then raise exception 'M4_TARGET_GUARD_FAILED:public_role_missing'; end if;
  if exists (select 1 from pg_roles where rolname in ('dpg_admin_m3_test','dpg_public_m3_test')) then raise exception 'M4_TARGET_GUARD_FAILED:test_roles_present'; end if;
  if (select count(*) from dpg_app.products) < 5000 then raise exception 'M4_TARGET_GUARD_FAILED:catalogue_size'; end if;
  if not exists (select 1 from dpg_control.target_contract where project_name = 'dongphugia-runtime') then raise exception 'M4_TARGET_GUARD_FAILED:project_contract'; end if;
  -- The Owner must record that Admin writes are authorised on this project (target_contract.production_writes_allowed = true)
  -- BEFORE this migration runs; the contract is never changed by this file.
  if exists (select 1 from dpg_control.target_contract where production_writes_allowed is not true) then raise exception 'M4_TARGET_GUARD_FAILED:production_writes_not_authorised'; end if;
end $$;`

export function generateProductionBase(options: BaseOptions) {
  const { role, policyPrefix } = options
  const policies = [
    ['admin_users', 'select'], ['admin_users', 'update'], ['admin_sessions', 'select'], ['admin_sessions', 'insert'], ['admin_sessions', 'delete'],
    ['admin_api_login_attempts', 'select'], ['admin_api_login_attempts', 'insert'], ['admin_api_login_attempts', 'delete'],
    ['admin_api_nonces', 'select'], ['admin_api_nonces', 'insert'], ['admin_api_nonces', 'delete'], ['audit_logs', 'insert'],
  ]
  const specs = policies.map(([t, c]) => `    ('${t}','${c}')`).join(',\n')
  const forward = [
    `-- ${options.title}`,
    '-- GENERATED by scripts/m4/generate-production-admin-migration.mts - do not edit by hand. Forward migration, idempotent.',
    '-- PRODUCTION (project bonxyxluzlxfkdetryoo). Run ONLY after: (1) a verified backup, (2) the Owner recorded production_writes_allowed = true.',
    'begin;',
    '-- guard:begin', options.guard.trim(), '-- guard:end', '',
    `do $$ begin if not exists (select 1 from pg_roles where rolname='${role}') then create role ${role} nologin nosuperuser nocreatedb nocreaterole noinherit noreplication nobypassrls; end if; end $$;`,
    `alter role ${role} set statement_timeout='10s';`,
    `alter role ${role} set search_path='dpg_app';`,
    `do $$ begin if exists (select 1 from pg_roles where rolname='postgres') then execute 'grant ${role} to postgres'; end if; end $$;`, '',
    '-- Additive: optimistic-lock token for products (blog_posts already has one). Constant default: no table rewrite.',
    'alter table dpg_app.products add column if not exists version integer not null default 1;', '',
    'create table if not exists dpg_app.admin_api_login_attempts (id bigserial primary key, key_hash text not null, created_at timestamptz not null default now());',
    'create index if not exists admin_api_login_attempts_key_created on dpg_app.admin_api_login_attempts (key_hash, created_at);',
    'create table if not exists dpg_app.admin_api_nonces (nonce text primary key, expires_at timestamptz not null);',
    'create index if not exists admin_api_nonces_expires on dpg_app.admin_api_nonces (expires_at);',
    'alter table dpg_app.admin_api_login_attempts enable row level security;', 'alter table dpg_app.admin_api_nonces enable row level security;', '',
    `grant usage on schema dpg_app to ${role};`,
    `grant select (id, email, name, password_hash, role, is_active, avatar_url) on dpg_app.admin_users to ${role};`,
    `grant update (last_login_at) on dpg_app.admin_users to ${role};`,
    `grant select, insert, delete on dpg_app.admin_sessions to ${role};`,
    `grant usage, select on sequence dpg_app.admin_sessions_id_seq to ${role};`,
    `grant select, insert, delete on dpg_app.admin_api_login_attempts to ${role};`,
    `grant usage, select on sequence dpg_app.admin_api_login_attempts_id_seq to ${role};`,
    `grant select, insert, delete on dpg_app.admin_api_nonces to ${role};`,
    `grant insert on dpg_app.audit_logs to ${role};`,
    `grant usage, select on sequence dpg_app.audit_logs_id_seq to ${role};`, '',
    'do $$', 'declare spec record;', 'begin', '  for spec in select * from (values', specs, '  ) as t(tbl,cmd) loop',
    `    execute format('drop policy if exists %I on dpg_app.%I', '${policyPrefix}'||spec.cmd, spec.tbl);`,
    "    if spec.cmd='insert' then",
    `      execute format('create policy %I on dpg_app.%I for insert to ${role} with check (true)', '${policyPrefix}'||spec.cmd, spec.tbl);`,
    "    elsif spec.cmd='update' then",
    `      execute format('create policy %I on dpg_app.%I for update to ${role} using (true) with check (true)', '${policyPrefix}'||spec.cmd, spec.tbl);`,
    '    else',
    `      execute format('create policy %I on dpg_app.%I for %s to ${role} using (true)', '${policyPrefix}'||spec.cmd, spec.tbl, spec.cmd);`,
    '    end if;', '  end loop;', 'end $$;', '',
    `do $$ declare r text; begin foreach r in array array['anon','authenticated'] loop if exists (select 1 from pg_roles where rolname = r) then execute format('revoke all on dpg_app.admin_api_login_attempts from %I', r); execute format('revoke all on dpg_app.admin_api_nonces from %I', r); end if; end loop; end $$;`, 'commit;', '',
  ].join('\n')
  const rollback = [
    `-- Rollback of: ${options.title}`,
    '-- Removes the role, policies and support tables. products.version is deliberately KEPT (harmless; dropping it is a separate decision).', '',
    'do $$ declare p record; begin for p in select schemaname, tablename, policyname from pg_policies where schemaname = \'dpg_app\' and policyname like \'' + policyPrefix + '%\' loop execute format(\'drop policy if exists %I on %I.%I\', p.policyname, p.schemaname, p.tablename); end loop; end $$;',
    'drop table if exists dpg_app.admin_api_nonces;', 'drop table if exists dpg_app.admin_api_login_attempts;',
    `do $$ begin if exists (select 1 from pg_roles where rolname='${role}') then execute 'revoke ${role} from postgres'; execute 'drop owned by ${role}'; execute 'drop role ${role}'; end if; end $$;`, '',
  ].join('\n')
  return { forward, rollback }
}
